package yagen.waitmydawn.kb.service;
import org.junit.jupiter.api.Test;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.List;import java.awt.*;import static org.junit.jupiter.api.Assertions.*;
class ChestLootRendererTest {
 @Test void emptyEntryIsNotConfusedWithNestedTable()throws Exception {var json=new ObjectMapper();assertEquals("空",ChestLootRenderer.placeholder(json.readTree("{\"type\":\"minecraft:empty\"}")));assertEquals("引用表",ChestLootRenderer.placeholder(json.readTree("{\"type\":\"minecraft:loot_table\",\"name\":\"minecraft:chests/test\"}")));}
 @Test void probabilitiesCountsColorsAndCommonFontRespectPoolSemantics()throws Exception {
  var json=new ObjectMapper();var root=json.readTree("{\"pools\":[{\"rolls\":{\"type\":\"minecraft:uniform\",\"min\":1,\"max\":4},\"entries\":[{\"type\":\"minecraft:item\",\"name\":\"minecraft:diamond\",\"weight\":1,\"functions\":[{\"function\":\"minecraft:set_count\",\"count\":{\"type\":\"minecraft:uniform\",\"min\":1,\"max\":4}}]},{\"type\":\"minecraft:item\",\"name\":\"minecraft:iron_ingot\",\"weight\":2},{\"type\":\"minecraft:item\",\"name\":\"minecraft:gold_ingot\",\"weight\":7}]}]}");
  var pool=ChestLootRenderer.pools(root).getFirst();assertEquals("1-4",ChestLootRenderer.number(pool.rule().path("rolls")));assertEquals("1-4",pool.slots().getFirst().count());assertEquals("10%",ChestLootRenderer.percent(pool.slots().getFirst().probability()));
  assertEquals(new Color(0xff55ff),ChestLootRenderer.probabilityColor(.1,pool.slots()));assertEquals(new Color(0x55ffff),ChestLootRenderer.probabilityColor(.2,pool.slots()));assertEquals(new Color(0xffff55),ChestLootRenderer.probabilityColor(.7,pool.slots()));assertEquals("100%",ChestLootRenderer.percent(1.));assertEquals("1.2%",ChestLootRenderer.percent(.01234));assertEquals("5.0%",ChestLootRenderer.percent(.05));assertEquals(new Color(0xffff55),ChestLootRenderer.probabilityColor(.2,pool.slots().subList(0,2)));assertEquals("?",ChestLootRenderer.percent(null));
  var graphics=new java.awt.image.BufferedImage(8,8,2).createGraphics();try{int size=ChestLootRenderer.fontSize(graphics,List.of(pool));graphics.setFont(yagen.waitmydawn.kb.renderer.CardFont.at(Font.BOLD,size));for(var slot:pool.slots())for(String text:List.of(ChestLootRenderer.percent(slot.probability()),slot.count()))assertTrue(graphics.getFontMetrics().stringWidth(text)<=92);}finally{graphics.dispose();}
 }
 @Test void conditionsAndNestedCompetitionAreNotReportedAsGuaranteedDrops()throws Exception {
  var root=new ObjectMapper().readTree("{\"pools\":[{\"rolls\":1,\"conditions\":[{\"condition\":\"minecraft:random_chance\",\"chance\":0.25}],\"entries\":[{\"type\":\"minecraft:item\",\"name\":\"minecraft:stone\"}]},{\"rolls\":1,\"entries\":[{\"type\":\"minecraft:alternatives\",\"children\":[]}]}]}");var pools=ChestLootRenderer.pools(root);assertEquals("25%",ChestLootRenderer.percent(pools.getFirst().slots().getFirst().probability()));assertEquals(new Color(0x55ffff),ChestLootRenderer.probabilityColor(.25,pools.getFirst().slots()));assertNull(pools.getLast().slots().getFirst().probability());
 }
}
